/* need to manually correspond to the dropdown list of UI */
#define DROPDOWN_SEL_OPT_0 (5000)
#define DROPDOWN_SEL_OPT_1 (15000)
#define DROPDOWN_SEL_OPT_2 (30000)
#define DROPDOWN_SEL_OPT_3 (60000)
