        break;
    case 1:
        backlight_value = DROPDOWN_SEL_OPT_1;
        break;
    case 2:
        backlight_value = DROPDOWN_SEL_OPT_2;
        break;
    case 3:
        backlight_value = DROPDOWN_SEL_OPT_3;
        break;
    case 4:
        backlight_value = DROPDOWN_SEL_OPT_4;
