void BacklightPnlBlCtrlKey(lv_event_t *e)
{
    // Your code here
    uint32_t key = lv_indev_get_key(lv_indev_get_act());
    switch (key) {
    case LV_KEY_BACKSPACE:
        lv_indev_wait_release(lv_indev_get_act());
        alv_am_win_exit(NULL, "backlight", NULL);
        break;
    case LV_KEY_RIGHT:
        _ui_slider_increment(ui_SliderBlCtrl, BRIGHTNESS_STEP_VALUE, LV_ANIM_ON);
        LV_LOG_USER("backlight :BL=%d\n", lv_slider_get_value(ui_SliderBlCtrl));
        break;
    case LV_KEY_LEFT: {
        uint32_t brightness_value = 0;
        brightness_value = (uint32_t)lv_slider_get_value(ui_SliderBlCtrl);
        /* be sure backlight level greater 1 */
        if(1 == brightness_value) {
            break;
        }
        _ui_slider_increment(ui_SliderBlCtrl, -BRIGHTNESS_STEP_VALUE, LV_ANIM_ON);
        LV_LOG_USER("backlight: BL:=%d\n", lv_slider_get_value(ui_SliderBlCtrl));
        break;
    }
    case LV_KEY_DOWN:
    case LV_KEY_UP:
        lv_group_focus_obj(ui_DrpdwnBlTime);
        break;
    default:
        LV_LOG_USER("backlight: Undefined keystroke event");
        break;
    }
}

void BacklightDrpdwnBlTimeKey(lv_event_t *e)
{
    // Your code here
    static int32_t enter_flag = DROPDOWN_IS_CLOSE;
    uint32_t key = lv_indev_get_key(lv_indev_get_act());
    switch (key) {
    case LV_KEY_BACKSPACE:
        if (enter_flag == DROPDOWN_IS_CLOSE) {
            lv_indev_wait_release(lv_indev_get_act());
            alv_am_win_exit(NULL, "backlight", NULL);
        }
        else if (enter_flag == DROPDOWN_IS_OPEN){
            lv_dropdown_close(ui_DrpdwnBlTime);
        }
        enter_flag = DROPDOWN_IS_CLOSE;
        break;
    case LV_KEY_UP:
    case LV_KEY_DOWN:
        if (enter_flag == DROPDOWN_IS_CLOSE) {
            lv_group_focus_obj(ui_PnlBlCtrl);
        }
        break;
    case LV_KEY_ENTER:
        enter_flag++;
        if (enter_flag == DROPDOWN_WAITC_CLOSE) {
            enter_flag = DROPDOWN_IS_CLOSE;
        }
        break;
    case LV_KEY_HOME:
        lv_event_send(ui_DrpdwnBlTime, LV_EVENT_RELEASED, NULL);

        enter_flag++;
        if (enter_flag == DROPDOWN_WAITC_CLOSE) {
            enter_flag = DROPDOWN_IS_CLOSE;
        }
        break;
    case LV_KEY_LEFT:
    case LV_KEY_RIGHT:
        if (enter_flag == DROPDOWN_IS_CLOSE) {
            enter_flag++;
        }
        break;
    default:
        LV_LOG_USER("backlight: Undefined keystroke event");
        break;
    }
}

void BacklightScreenLoaded(lv_event_t * e)
{
	// Your code here
    uint32_t backlight_value = 0;
    uint32_t brightness = 0;
    brightness = settings_flow_get_brightness();
    backlight_value = settings_flow_get_backlight_value();

    uint16_t sel_opt = 0;
    switch (backlight_value) {
    case DROPDOWN_SEL_OPT_0:
        sel_opt = 0;
        break;
    case DROPDOWN_SEL_OPT_1:
        sel_opt = 1;
        break;
    case DROPDOWN_SEL_OPT_2:
        sel_opt = 2;
        break;
    case DROPDOWN_SEL_OPT_3:
        sel_opt = 3;
        break;
    case DROPDOWN_SEL_OPT_4:
        sel_opt = 4;
        break;
    case DROPDOWN_SEL_OPT_5:
        sel_opt = 5;
        break;
    default:
        LV_LOG_ERROR("dropdown list and init cannot correspond");
        break;
    }
    brightness = brightness/20;
    /* in ui layer, brightness range 1~5; in flow layer,brightness range 1~100 */
    lv_slider_set_value(ui_SliderBlCtrl, brightness, LV_ANIM_OFF);
    _ui_slider_set_text_value( ui_LblBlValue, ui_SliderBlCtrl, "", "");
    lv_dropdown_set_selected(ui_DrpdwnBlTime, sel_opt);

    SHOW_STATUSBAR_SUB_WIN("Display");
}
